def _read(path):
    return path.read_text(encoding="utf-8")


def _section(text, heading):
    match = re.search(rf"^## {re.escape(heading)}\n(?P<body>.*?)(?=^## |\Z)", text, re.M | re.S)
    assert match is not None
    return match.group("body")


def _exact(text, heading):
    assert _section(text, heading) == EXPECTED_SECTION_BODIES[heading]


def _numbered_code_items(body):
    return [match.group(1) for match in re.finditer(r'^\d+\. `([^`]+)`$', body, re.M)]


def validate_exact_section_bodies(text):
    assert [line[3:] for line in text.splitlines() if line.startswith("## ")] == EXPECTED_HEADINGS
    assert {heading: _section(text, heading) for heading in EXPECTED_HEADINGS} == EXPECTED_SECTION_BODIES


