def _literal(node):
    if isinstance(node, ast.Constant):
        return True
    if isinstance(node, (ast.List, ast.Tuple)):
        return all(_literal(item) and not isinstance(item, ast.Starred) for item in node.elts)
    if isinstance(node, ast.Dict):
        return all(key is not None and _literal(key) and _literal(value) for key, value in zip(node.keys, node.values))
    return False


def test_all_expected_oracles_are_single_recursive_literals():
    tree = ast.parse(_read(SELF_PATH))
    found = {}
    for node in tree.body:
        if isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name) and target.id.startswith("EXPECTED_"):
                    found.setdefault(target.id, []).append(node.value)
        elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name) and node.target.id.startswith("EXPECTED_"):
            found.setdefault(node.target.id, []).append(node.value)
    assert found
    assert all(len(values) == 1 and _literal(values[0]) for values in found.values())
    assert "EXPECTED_SECTION_BODIES" in found and len(EXPECTED_SECTION_BODIES) == 29
    for values in found.values():
        for node in ast.walk(values[0]):
            assert not isinstance(node, (ast.Name, ast.Attribute, ast.Subscript, ast.Call, ast.BinOp, ast.JoinedStr, ast.ListComp, ast.SetComp, ast.DictComp, ast.GeneratorExp, ast.Starred, ast.Set))


def test_static_source_imports_reads_and_executable_safety():
    tree = ast.parse(_read(SELF_PATH))
    imports = []
    forbidden_names = {"open", "eval", "exec", "__import__"}
    forbidden_attrs = {"open", "write_text", "write_bytes", "touch", "unlink", "rename", "mkdir", "rmdir", "chmod", "symlink_to", "hardlink_to", "link_to", "system", "popen"}
    forbidden_roots = {"os", "subprocess", "socket", "sqlite3", "duckdb", "requests", "urllib", "http", "importlib"}
    for node in tree.body:
        if isinstance(node, ast.Import):
            imports.extend(alias.name for alias in node.names)
        elif isinstance(node, ast.ImportFrom):
            raise AssertionError("from-import is not allowed")
    assert imports == ["ast", "pathlib", "re"]
    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            if isinstance(node.func, ast.Name):
                assert node.func.id not in forbidden_names
            if isinstance(node.func, ast.Attribute):
                assert node.func.attr not in forbidden_attrs
        if isinstance(node, ast.Constant) and isinstance(node.value, str) and node.value.startswith("." + "git/"):
            raise AssertionError("git path access")
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            names = [alias.name.split(".")[0] for alias in node.names]
            assert not set(names) & forbidden_roots
    reads = [node for node in ast.walk(tree) if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == "read_text"]
    assert len(reads) == 1
    read_calls = [node for node in ast.walk(tree) if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == "_read"]
    assert len(read_calls) == 7


def _assignment(tree, name, kind):
    matches = []
    for node in tree.body:
        if isinstance(node, ast.Assign) and any(isinstance(target, ast.Name) and target.id == name for target in node.targets):
            assert isinstance(node.value, kind)
            matches.append(node.value)
        elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name) and node.target.id == name:
            assert isinstance(node.value, kind)
            matches.append(node.value)
    assert len(matches) == 1
    return matches[0]


def test_allowlist_registry_mapping_and_observed_counts_are_path_specific():
    source = _read(ALLOWLIST_PATH)
    tree = ast.parse(source)
    registry = _assignment(tree, "_ARCH_ALIGN_03_DOWNSTREAM_ARTIFACTS", ast.Set)
    mapping_wrapper = _assignment(tree, "ALLOWED_MARKET_ID_OCCURRENCE_LINES", ast.Call)
    assert isinstance(mapping_wrapper.func, ast.Name) and mapping_wrapper.func.id == "_MarketIdAllowlist"
    assert len(mapping_wrapper.args) == 1 and isinstance(mapping_wrapper.args[0], ast.Dict)
    mapping = mapping_wrapper.args[0]
    registry_values = [item.value for item in registry.elts if isinstance(item, ast.Constant) and isinstance(item.value, str)]
    pairs = [(key.value, value) for key, value in zip(mapping.keys, mapping.values) if isinstance(key, ast.Constant) and isinstance(key.value, str)]
    for path, expected_count in EXPECTED_ALLOWLIST_COUNTS.items():
        assert registry_values.count(path) == 1
        selected = [value for key, value in pairs if key == path]
        assert len(selected) == 1 and isinstance(selected[0], ast.Constant) and type(selected[0].value) is int
        observed = sum(bool(re.search(r"(?<![A-Za-z0-9_])market_id(?![A-Za-z0-9_])", line)) for line in _read(REPO_ROOT / path).splitlines())
        assert selected[0].value == expected_count == observed
